'use strict';
const fs=require('fs'),path=require('path');
const DIR=__dirname;
const all=[];
function row(act,s,sec,t,d,ch,cat,kw){
  all.push({act,act_short:s,section:String(sec),section_title:t,
    section_desc:d,chapter:String(ch),chapter_title:'',category:cat,
    keywords:Array.isArray(kw)?kw:String(kw).split(' ')});
}

// Helper to batch-add entries
function addAll(act,s,cat,arr){
  arr.forEach(([sec,t,d,ch,kw])=>row(act,s,sec,t,d,ch,cat,kw));
}

// ═══════════════════════════════════════════════════════
// IPC SECTIONS — Chapters 5-23 (abetment through attempt)
// ═══════════════════════════════════════════════════════
addAll("Indian Penal Code, 1860","IPC","Criminal Law",[
["107","Abetment — three modes","Abetment means: (1) Instigation — actively suggesting/stimulating a person to commit an act; (2) Conspiracy — engaging with one or more persons to commit an act, where some act in pursuance occurs; (3) Intentional aid — doing any act that helps commission. All three modes require mensrea — the abettor must share the intention/knowledge of the principal offender. Mere acquiescence is not abetment. Presence at scene + knowledge = abetment.","5",["IPC S107 abetment three modes instigation conspiracy aid mensrea intention knowledge principal offender acquiescence"]],
["108","Abettor defined","A person abets an offence who abets either the commission of an offence, or the commission of an act which would be an offence if committed by a person capable by law of committing an offence with the same intention or knowledge. An abettor need not be physically present. The act abetted need not occur for abetment to be complete (see S.115, S.116).","5",["IPC S108 abettor defined capable intention knowledge need not present act need not occur complete"]],
["109","Punishment when act abetted is committed in consequence","If the abetted act is committed in consequence of the abetment, and no express provision exists for punishment of such abetment, the abettor gets the same punishment as the principal offender. Key: a causal connection between abetment and act must be established. Conspiracy (S.120A): even if act is not committed, conspiracy to commit serious offence is punishable.","5",["IPC S109 punishment abettor same as principal causal connection abetment act committed consequence"]],
["110","Punishment when person abetted acts with different intention","The abettor is punished for the offence he intended, not the offence actually committed. If A instigates B to assault C but B actually murders C, A is guilty of abetment of assault, not abetment of murder (unless A knew murder was likely).","5",["IPC S110 different intention abettor punished own intention knowledge not actual offence"]],
["111","Liability when different act done in consequence of abetment","When the act done is different from what was abetted, abettor is liable if the different act was a probable consequence of the abetment and was done under the influence of the instigation. Doctrine of probable consequences.","5",["IPC S111 probable consequences abetment different act instigation influence liable abettor"]],
["113","Liability for different effect from abetted act","If the abettor intended a particular effect but a different effect occurred, and the abettor knew the act was likely to cause that different effect, he is liable for the different effect. Knowledge of likely consequence is key.","5",["IPC S113 different effect abettor knew likely caused liable"]],
["114","Abettor present when offence committed — treated as principal","If an abettor who would normally be punished for abetment is present when the offence is actually committed, he shall be deemed to have committed the offence himself. Constructive commission.","5",["IPC S114 abettor present offence committed deemed committed constructive commission"]],
["115","Abetment of offence punishable with death or life — offence not committed","If the abetted offence is punishable with death or life imprisonment but is NOT committed, the abettor is punishable with up to seven years imprisonment + fine. If harm is caused as result: up to fourteen years + fine.","5",["IPC S115 abetment death life offence not committed seven years fourteen years harm caused fine"]],
["116","Abetment of offence punishable with imprisonment — offence not committed","If an offence punishable with imprisonment is abetted but not committed, the abettor can be imprisoned for up to one-fourth of the maximum term for that offence. If abettor/abetted person is public servant whose duty it is to prevent the offence: up to one-half.","5",["IPC S116 abetment imprisonment not committed one-fourth public servant duty one-half"]],
["117","Abetting commission of offence by more than ten persons","Whoever abets the commission of an offence by the public generally or by any number or class of persons exceeding ten, shall be punished with imprisonment up to three years, or fine, or both.","5",["IPC S117 abetting public ten persons three years fine general"]],
["118","Concealing design to commit offence punishable with death — voluntary concealment","Voluntarily concealing existence of a design to commit an offence punishable with death or life imprisonment: if offence committed — seven years + fine; if not committed — three years + fine.","5",["IPC S118 concealing design death life voluntary seven years three years fine"]],
["119","Public servant concealing design to prevent offence","A public servant who knowingly facilitates an offence it is his duty to prevent, by voluntarily concealing a design to commit it: liable for half the punishment for the offence.","5",["IPC S119 public servant conceal design prevent offence half punishment duty"]],
["120","Concealing design to commit offence punishable with imprisonment","Voluntary concealment of design to commit offence punishable with imprisonment: if offence committed — one-fourth of the longest term; if not committed — one-eighth.","5",["IPC S120 concealing design imprisonment one-fourth one-eighth voluntary"]],
["120A","Criminal conspiracy — definition","Two or more persons agree to do or cause to be done: (1) an illegal act; or (2) a lawful act by illegal means. This agreement itself is criminal conspiracy. For serious offences (death/life/rigorous imprisonment 2+ years): no overt act needed beyond the agreement. For less serious: some overt act must be done.","5",["IPC S120A criminal conspiracy two persons agree illegal act illegal means agreement overt act serious less serious"]],
["120B","Punishment for criminal conspiracy","If conspiracy is to commit offence punishable with death, life or rigorous imprisonment for 2+ years: same punishment as abetment of that offence. Other conspiracies: imprisonment up to 6 months, or fine, or both.","5",["IPC S120B punishment conspiracy death life two years same abetment six months fine"]],
["121","Waging or attempting to wage war against Government of India","Death, or life imprisonment + fine. Includes: actual waging of war; attempting to wage war; abetting waging of war. The three variants are all equally punishable with the maximum. 'Waging war' means armed conflict with intention to overawe the government — not mere civil disorder.","6",["IPC S121 waging war government India death life imprisonment attempt abetment overawe armed conflict"]],
["121A","Conspiracy to commit offences under S.121","Punishment: life imprisonment or up to 10 years + fine. Conspiracy to overawe (by criminal force/threat) the Central or any State Government. Conspiracy alone is punishable — no overt act needed.","6",["IPC S121A conspiracy war S121 life ten years overawe Central State Government criminal force"]],
["122","Collecting arms with intent to wage war","Collecting men, arms or ammunition or otherwise preparing to wage war against the Government of India: life imprisonment or up to 10 years + fine.","6",["IPC S122 collecting arms ammunition men prepare wage war life ten years"]],
["123","Concealing with intent to facilitate war","Concealing existence of a design to wage war against the Government of India with intent to facilitate such war: imprisonment up to 10 years + fine.","6",["IPC S123 concealing design wage war facilitate ten years fine"]],
["124","Assault on President/Governor to compel exercise of power","Assaulting or wrongfully restraining or overawing by criminal force the President of India or Governor of any State to compel/prevent exercise of lawful powers: imprisonment up to 7 years + fine.","6",["IPC S124 assault President Governor compel restrain overawe seven years fine"]],
["124A","Sedition (now replaced by BNS S.152)","Whoever by words (spoken/written), signs, or visible representation excites or attempts to excite disaffection towards the Government established by law in India: life imprisonment (or imprisonment up to 3 years) + fine. Struck down in 2022 by SC (SG Vombatkere). Replaced by BNS 2023 S.152.","6",["IPC S124A sedition disaffection life imprisonment three years struck down 2022 SC BNS 152"]],
["125","Waging war against Asiatic Power in alliance with India","Waging war or abetting war against the Government of any Asiatic Power in alliance with India: life imprisonment or imprisonment up to 7 years + fine.","6",["IPC S125 war Asiatic Power alliance life seven years fine"]],
["126","Committing depredation on territories of Power at peace","Committing depredation or preparing to commit depredation on territories of any Power in alliance or at peace with India: imprisonment up to 7 years + fine + forfeiture.","6",["IPC S126 depredation territories power peace alliance seven years fine forfeiture"]],
["128","Public servant allowing prisoner of State/war to escape","A public servant having custody of a prisoner of State or war, who voluntarily allows such prisoner to escape: life imprisonment or up to 10 years + fine.","6",["IPC S128 public servant prisoner state war escape voluntarily life ten years"]],
["129","Public servant negligently suffering prisoner to escape","Public servant having custody of prisoner of State/war who negligently suffers escape: simple imprisonment up to 3 years + fine.","6",["IPC S129 negligently prisoner state war escape three years fine"]],
["130","Aiding escape of prisoner of State or war","Aiding, assisting, harbouring escaped prisoner of State or war: life imprisonment or up to 10 years + fine.","6",["IPC S130 aiding harbouring prisoner state war life ten years"]],
["131","Abetting mutiny or seducing soldier from duty","Abetting mutiny or attempting to seduce any officer, soldier, sailor or airman from allegiance/duty: life imprisonment or up to 10 years + fine.","7",["IPC S131 mutiny seduce soldier sailor airman duty life ten years"]],
["132","Abetment of mutiny if mutiny committed","If mutiny committed in consequence of abetment: death or life imprisonment or up to 10 years + fine.","7",["IPC S132 abetment mutiny committed death life ten years"]],
["133","Abetment of assault by soldier on superior officer","Abetting assault by soldier on superior officer: up to 3 years + fine.","7",["IPC S133 abetment assault soldier superior officer three years fine"]],
["140","Wearing garb of soldier — unauthorized","Wearing garb or carrying token resembling that of a soldier/sailor/airman with intent to be believed to be one: up to 3 months or fine up to Rs 500.","7",["IPC S140 wearing garb soldier three months five hundred unauthorized"]],
["141","Unlawful assembly — five or more persons with common object","Common object must be one of: overawe by criminal force; resist execution of law; commit mischief/trespass; by criminal force take/obtain property; by criminal force compel any person. All five must have the common object for S.141 to apply.","8",["IPC S141 unlawful assembly five persons common object overawe resist mischief criminal force"]],
["143","Punishment for being member of unlawful assembly","Imprisonment up to 6 months, or fine, or both.","8",["IPC S143 member unlawful assembly six months fine punishment"]],
["144","Joining unlawful assembly armed with deadly weapon","Being armed with a deadly weapon as member of unlawful assembly: up to 2 years or fine or both.","8",["IPC S144 armed deadly weapon unlawful assembly two years fine"]],
["145","Joining or continuing after commanded to disperse","Imprisonment up to 2 years or fine or both.","8",["IPC S145 joining continuing unlawful assembly commanded disperse two years"]],
["146","Rioting — definition","Rioting occurs when force or violence is used by an unlawful assembly, or by any member, in prosecution of the common object. Every member is guilty even if only some used force.","8",["IPC S146 rioting force violence unlawful assembly common object every member guilty"]],
["147","Punishment for rioting","Imprisonment up to 2 years or fine or both.","8",["IPC S147 rioting two years fine punishment"]],
["148","Rioting armed with deadly weapon","Imprisonment up to 3 years or fine or both.","8",["IPC S148 rioting deadly weapon three years fine"]],
["149","Common object — vicarious liability","Every member of an unlawful assembly is guilty of offences committed by any member in prosecution of the common object, OR offences which the members knew to be likely to be committed. Test: subjective knowledge of likely offence — not merely objective probability.","8",["IPC S149 common object every member guilty prosecution knew likely committed vicarious"]],
["151","Knowingly joining or continuing in assembly of five or more after commanded to disperse","Imprisonment up to 6 months or fine or both.","8",["IPC S151 joining continuing assembly five persons commanded disperse six months"]],
["152","Assaulting public servant suppressing riot","Assaulting or obstructing public servant endeavouring to disperse unlawful assembly or suppress riot: up to 3 years or fine or both.","8",["IPC S152 assault public servant suppress riot three years fine"]],
["153","Giving provocation to cause riot","Malignantly giving provocation likely to cause rioting: if riot committed — 1 year; if not — 6 months.","8",["IPC S153 provocation riot one year six months malignantly"]],
["153A","Promoting enmity between groups","Promotes or attempts to promote disharmony, enmity, hatred or ill-will between groups on grounds of religion, race, caste, community, language: up to 3 years or fine or both. In place of worship: up to 5 years + fine.","8",["IPC S153A promoting enmity disharmony religion race caste three years five years place worship"]],
["153B","Imputations prejudicial to national integration","Asserting that class of persons based on religion/caste/language cannot bear allegiance to Constitution of India or that they be denied rights as citizens: up to 3 years or fine or both.","8",["IPC S153B national integration imputation Constitution India deny rights caste religion three years"]],
["159","Affray","Two or more persons fighting in a public place disturbing public peace commit an affray.","8",["IPC S159 affray two persons fighting public place disturb peace"]],
["160","Punishment for affray","Imprisonment up to 1 month or fine up to Rs 100 or both.","8",["IPC S160 affray one month hundred rupees fine"]],
["166","Public servant disobeying law to cause injury","Public servant knowingly disobeying law as to his conduct with intent to cause injury to any person: simple imprisonment up to 1 year or fine or both.","9",["IPC S166 public servant disobeying law injury one year fine"]],
["166A","Public servant disobeying direction under law","Public servant failing to record FIR for specified offences (rape, acid attack, trafficking) or disobeying investigation direction: rigorous imprisonment 6 months to 2 years + fine.","9",["IPC S166A FIR failure record rape acid attack trafficking rigorous six months two years fine"]],
["166B","Punishment for non-treatment of victim","Hospital (public/private) failing to provide free first-aid or medical treatment to victim of acid attack or rape: imprisonment up to 1 year or fine or both.","9",["IPC S166B hospital non-treatment victim acid attack rape one year fine free treatment"]],
["167","Public servant framing incorrect document","Public servant framing incorrect document or translation to cause injury: imprisonment up to 3 years or fine or both.","9",["IPC S167 public servant incorrect document translation injury three years fine"]],
["170","Personating public servant","Pretending to hold office of public servant and acting under colour of that office: imprisonment up to 2 years or fine or both.","9",["IPC S170 personating public servant pretend colour office two years fine"]],
["172","Absconding to avoid service of summons","Simple imprisonment up to 1 month or fine up to Rs 500 or both. If summons for court appearance: 6 months or Rs 1,000.","10",["IPC S172 absconding summons one month five hundred court six months"]],
["177","Furnishing false information to public servant","Simple imprisonment up to 6 months or fine up to Rs 1,000 or both.","10",["IPC S177 false information public servant six months one thousand"]],
["186","Obstructing public servant","Voluntarily obstructing public servant in discharge of public functions: imprisonment up to 3 months or fine up to Rs 500.","10",["IPC S186 obstruct public servant three months five hundred"]],
["188","Disobedience to order of public servant","If causing obstruction/annoyance: simple imprisonment up to 1 month or fine Rs 200. If causing danger to life/health/safety: 6 months or Rs 1,000.","10",["IPC S188 disobedience public servant obstruction one month two hundred danger six months thousand"]],
["193","Punishment for false evidence","False evidence in judicial proceeding: imprisonment up to 7 years + fine. False evidence in any other case: imprisonment up to 3 years + fine.","11",["IPC S193 false evidence judicial seven years three years fine"]],
["195A","Threatening person to give false evidence","Threatening another with injury to person/reputation/property to give false evidence: imprisonment up to 7 years or fine or both. If innocent person convicted: same punishment as innocent person received.","11",["IPC S195A threatening false evidence seven years injury reputation property innocent person same punishment"]],
["201","Causing disappearance of evidence to screen offender","Causing evidence to disappear or giving false information to screen offender from punishment: if offence punishable with death — 7 years; if life imprisonment — 3 years; others — one-fourth of longest term.","11",["IPC S201 disappearance evidence screen offender death seven years life three years one-fourth"]],
["204","Destruction of document to prevent production","Destroying/obscuring document that can be compelled to produce as evidence in court: imprisonment up to 2 years or fine or both.","11",["IPC S204 destroy document prevent production evidence two years fine"]],
["211","False charge of offence with intent to injure","Instituting false criminal proceedings or falsely charging with offence knowing no lawful ground: up to 2 years or fine. If charge of capital offence: 7 years.","11",["IPC S211 false charge intent injure two years capital seven years"]],
["268","Public nuisance — definition","Act or omission causing common injury, danger or annoyance to the public or to persons in vicinity. Punishable under S.290 with fine up to Rs 200.","14",["IPC S268 S290 public nuisance common injury danger annoyance two hundred fine"]],
["279","Rash driving on public way","Driving rashly or negligently on a public way endangering human life or likely to cause hurt: imprisonment up to 6 months or fine up to Rs 1,000 or both.","14",["IPC S279 rash driving public way six months one thousand fine"]],
["295","Injuring or defiling place of worship","Destroying, damaging, or defiling place of worship or sacred object with intent to insult religion: imprisonment up to 2 years or fine or both.","15",["IPC S295 injuring defiling place worship insult religion two years fine"]],
["295A","Deliberate acts outraging religious feelings","Deliberate and malicious acts intending to outrage religious feelings by insulting religion or religious beliefs: imprisonment up to 3 years or fine or both.","15",["IPC S295A deliberate malicious outrage religious feelings insult three years fine"]],
["296","Disturbing religious assembly","Voluntarily causing disturbance to assembly engaged in religious worship: imprisonment up to 1 year or fine or both.","15",["IPC S296 disturbing religious assembly worship one year fine"]],
["297","Trespassing on burial places","Trespass in place of worship/burial ground with intent to wound religious feelings or insult religion: imprisonment up to 1 year or fine or both.","15",["IPC S297 trespassing burial place worship insult religion one year fine"]],
["298","Uttering words to wound religious feelings","Deliberately uttering words/sounds/gestures to wound religious feelings of any person: imprisonment up to 1 year or fine or both.","15",["IPC S298 uttering words wound religious feelings one year fine deliberate"]],
["299","Culpable homicide — definition","Causing death with: (a) intention of causing death; (b) intention of causing such bodily injury as is likely to cause death; (c) knowledge that act is likely to cause death. Not murder if it falls within S.300 exceptions. The distinguishing element from murder is the degree of intention/knowledge.","16",["IPC S299 culpable homicide death intention bodily injury knowledge likely not murder exceptions degree"]],
["300","Murder — exceptions to culpable homicide","Culpable homicide is murder UNLESS within five exceptions: (1) Grave and sudden provocation — no premeditation, provocation by deceased; (2) Exceeding right of private defence in good faith; (3) Public servant in good faith in discharge of duty; (4) Sudden fight without premeditation; (5) Consent of person above 18 years to cause death.","16",["IPC S300 murder exceptions provocation private defence public servant sudden fight consent reduces to culpable homicide"]],
["302","Punishment for murder","Death or imprisonment for life + fine. 'Rarest of rare' doctrine (Bachan Singh 1980): death penalty only in cases of extreme culpability. Court must give accused hearing on question of sentence (S.235(2) CrPC). Mitigating factors must be considered.","16",["IPC S302 murder death life fine rarest of rare Bachan Singh hearing sentence mitigating"]],
["303","Punishment for murder by life-convict","Whoever being under sentence of life imprisonment commits murder: death penalty (mandatory). SC in Mithu Singh (1983) struck this down as unconstitutional. Now S.302 applies.","16",["IPC S303 life convict murder death mandatory Mithu Singh struck down unconstitutional S302 applies"]],
["304","Culpable homicide not amounting to murder","Part I (intention): life imprisonment or up to 10 years + fine. Part II (knowledge without intention): imprisonment up to 10 years or fine or both. The distinction between Part I and Part II depends on whether there was intention to cause death or mere knowledge.","16",["IPC S304 culpable homicide Part I Part II life ten years intention knowledge difference punishment"]],
["304A","Causing death by negligence","Whoever causes death of any person by doing any rash or negligent act not amounting to culpable homicide: imprisonment up to 2 years or fine or both. Medical negligence: Jacob Mathew (2005) — gross negligence required.","16",["IPC S304A negligence death two years fine rash not culpable homicide Jacob Mathew gross medical"]],
["304B","Dowry death","Death of woman within 7 years of marriage + cruelty/harassment for dowry before death = dowry death. Minimum sentence: 7 years; maximum: life imprisonment. S.113B IEA: mandatory presumption of dowry death.","16",["IPC S304B dowry death seven years marriage cruelty harassment minimum seven years life S113B presumption"]],
["306","Abetment of suicide","If any person commits suicide, whoever abets the commission: imprisonment up to 10 years + fine.","16",["IPC S306 abetment suicide ten years fine"]],
["307","Attempt to murder","Act done with intention/knowledge that if death resulted it would be murder: imprisonment up to 10 years + fine. If hurt caused: life imprisonment. Even if victim survives, the offence is complete upon the act being done.","16",["IPC S307 attempt murder ten years life imprisonment hurt caused act done intention knowledge"]],
["308","Attempt to commit culpable homicide","Act done with intention/knowledge that if death resulted it would be culpable homicide not amounting to murder: imprisonment up to 3 years or fine or both. If hurt: up to 7 years or fine or both.","16",["IPC S308 attempt culpable homicide three years seven years hurt fine"]],
["309","Attempt to commit suicide","Attempt to commit suicide: simple imprisonment up to 1 year or fine or both. Practically defunct — Mental Healthcare Act 2017 S.115 creates rebuttable presumption of severe mental stress.","16",["IPC S309 attempt suicide one year practically defunct Mental Healthcare Act 2017 mental stress"]],
["312","Causing miscarriage","Voluntarily causing a pregnant woman to miscarry other than to save her life: if woman not quick with child — up to 3 years or fine or both; if quick with child — up to 7 years + fine.","16",["IPC S312 miscarriage pregnant woman not to save life three years seven years quick fine"]],
["313","Causing miscarriage without woman's consent","Whether woman quick with child or not: imprisonment for life or up to 10 years + fine.","16",["IPC S313 miscarriage without consent life ten years fine"]],
["323","Punishment for voluntarily causing hurt","Imprisonment up to 1 year or fine up to Rs 1,000 or both.","16",["IPC S323 voluntarily causing hurt one year thousand rupees fine"]],
["324","Voluntarily causing hurt by dangerous weapons","Using instruments for shooting, stabbing, cutting, or dangerous means to cause hurt: imprisonment up to 3 years or fine or both.","16",["IPC S324 hurt dangerous weapons three years fine stabbing cutting shooting"]],
["325","Punishment for voluntarily causing grievous hurt","Imprisonment up to 7 years + fine.","16",["IPC S325 grievous hurt seven years fine voluntarily"]],
["326","Voluntarily causing grievous hurt by dangerous weapons","Life imprisonment or imprisonment up to 10 years + fine.","16",["IPC S326 grievous hurt dangerous weapons life ten years fine"]],
["326A","Acid attack — causing permanent damage","Causing permanent or partial damage by throwing acid: minimum 10 years, may extend to life + fine (to meet medical expenses, paid to victim). The fine is mandatory and must be just and reasonable.","16",["IPC S326A acid attack minimum ten years life fine victim medical expenses mandatory permanent damage"]],
["326B","Attempting to throw acid","Attempting to throw or administer acid with intent to cause permanent damage: minimum 5 years, up to 7 years + fine.","16",["IPC S326B acid attack attempt five years seven years fine"]],
["341","Wrongful restraint","Voluntarily obstructing any person so as to prevent proceeding in any direction: simple imprisonment up to 1 month or fine Rs 500 or both.","16",["IPC S341 wrongful restraint one month five hundred fine"]],
["342","Wrongful confinement","Wrongfully restraining person within circumscribed limits: imprisonment up to 1 year or fine Rs 1,000 or both.","16",["IPC S342 wrongful confinement one year thousand rupees fine"]],
["354","Assault or criminal force to outrage modesty of woman","Minimum 1 year, maximum 5 years + fine. Essential element: the accused must have intended to outrage or known that modesty would be outraged. Even verbal acts with physical proximity can constitute this offence.","16",["IPC S354 modesty woman criminal force minimum one year five years fine intended outrage verbal"]],
["354A","Sexual harassment","Physical contact with unwelcome sexual advances; demand/request for sexual favours; showing pornography; sexually coloured remarks: 3 years or fine or both (first three); 1 year or fine (remarks).","16",["IPC S354A sexual harassment physical contact demand favours pornography remarks three years one year fine"]],
["354B","Assault to disrobe woman","Assaulting or using criminal force to woman with intent to disrobe or compel nakedness: minimum 3 years, maximum 7 years + fine.","16",["IPC S354B disrobe woman assault criminal force minimum three years seven years fine"]],
["354C","Voyeurism","Watching or capturing image of woman in private act in circumstances where she expects privacy: first conviction 1-3 years; subsequent 3-7 years + fine.","16",["IPC S354C voyeurism private act image first one three years subsequent seven years fine"]],
["354D","Stalking","Following/contacting woman repeatedly despite indication of disinterest; monitoring internet/email: first conviction 3 years; subsequent 5 years + fine.","16",["IPC S354D stalking following monitoring woman three years five years fine"]],
["363","Punishment for kidnapping","Imprisonment up to 7 years + fine.","16",["IPC S363 kidnapping seven years fine India guardianship"]],
["363A","Kidnapping or maiming minor for begging","Kidnapping minor or obtaining custody to use for begging: imprisonment up to 10 years + fine. Maiming minor for begging: life imprisonment + fine.","16",["IPC S363A kidnapping maiming minor begging ten years life imprisonment fine"]],
["364","Kidnapping or abducting to murder","Life imprisonment or rigorous imprisonment up to 10 years + fine.","16",["IPC S364 kidnapping murder life ten years fine rigorous"]],
["364A","Kidnapping for ransom","Kidnapping and threatening death/hurt to compel Government/person to pay ransom or do/abstain from act: death or life imprisonment + fine.","16",["IPC S364A kidnapping ransom death life imprisonment fine threaten government person"]],
["365","Kidnapping with intent to secretly confine","Imprisonment up to 7 years + fine.","16",["IPC S365 kidnapping secretly confine seven years fine"]],
["366","Kidnapping to compel marriage/illicit intercourse","Imprisonment up to 10 years + fine.","16",["IPC S366 kidnapping marriage illicit intercourse ten years fine"]],
["366A","Procuration of minor girl","Inducing minor girl under 18 to do any act with intent she may be forced to illicit intercourse: imprisonment up to 10 years + fine.","16",["IPC S366A procuration minor girl eighteen illicit intercourse ten years fine"]],
["367","Kidnapping to subject to grievous hurt/slavery","Imprisonment up to 10 years + fine.","16",["IPC S367 kidnapping grievous hurt slavery ten years fine"]],
["370","Trafficking of persons","Recruiting/transporting/receiving person through threats/force/deception for exploitation (sexual, slavery, organ removal): minimum 7 years, up to 10 years + fine. Multiple victims: minimum 10 years to life. Minors: minimum 10 years to life. Police/public servant involvement: life imprisonment.","16",["IPC S370 trafficking persons minimum seven years ten years minor life imprisonment police public servant"]],
["374","Unlawful compulsory labour","Whoever unlawfully compels any person to labour against his will: imprisonment up to 1 year or fine or both.","16",["IPC S374 compulsory labour against will one year fine"]],
["375","Rape — definition","Seven circumstances making sexual intercourse rape: (1) against her will; (2) without her consent; (3) consent by fear of death/hurt; (4) consent by deception (man impersonates husband); (5) consent when unable to understand due to intoxication/unsoundness; (6) when under 18 years; (7) when unable to communicate consent. Marital rape exception (wife not below 15) — under challenge at SC.","16",["IPC S375 rape definition seven circumstances against will consent fear deception intoxication eighteen marital exception challenge"]],
["376","Punishment for rape","Standard rape: minimum 10 years, up to life imprisonment + fine (to be paid to victim). Aggravated forms (police, public servant, armed forces, custody, pregnant, repeated, during communal violence): minimum 10 years, up to life + fine. Gang rape: minimum 20 years, up to life (natural life).","16",["IPC S376 rape minimum ten years life imprisonment fine victim aggravated police public servant pregnant gang minimum twenty years"]],
["376E","Punishment for repeat offenders","Whoever previously convicted under S.376, S.376A, S.376D and subsequently convicted under any of these sections: life imprisonment (natural life) or death.","16",["IPC S376E repeat offender rape life natural death previous conviction"]],
["379","Punishment for theft","Imprisonment up to 3 years or fine or both.","17",["IPC S379 theft three years fine punishment"]],
["380","Theft in dwelling house","Imprisonment up to 7 years + fine.","17",["IPC S380 theft dwelling house seven years fine"]],
["381","Theft by clerk or servant","Whoever being clerk or servant commits theft of property in possession of master/employer: imprisonment up to 7 years + fine.","17",["IPC S381 theft clerk servant master employer seven years fine"]],
["382","Theft after preparation for causing death or hurt","Making preparation for causing death, hurt or restraint in order to commit theft: rigorous imprisonment up to 10 years + fine.","17",["IPC S382 theft preparation death hurt restraint ten years fine rigorous"]],
["383","Extortion — definition","Intentionally putting person in fear of injury and thereby dishonestly inducing to deliver property/security. Distinguished from theft: victim is aware and delivers under fear. Distinguished from robbery: no immediate personal presence/violence needed.","17",["IPC S383 extortion definition fear injury dishonestly deliver property distinguished theft robbery"]],
["384","Punishment for extortion","Imprisonment up to 3 years or fine or both.","17",["IPC S384 extortion three years fine"]],
["386","Extortion by putting in fear of death or grievous hurt","Imprisonment up to 10 years + fine.","17",["IPC S386 extortion death grievous hurt ten years fine"]],
["390","Robbery — definition","Theft is robbery when in order to committing theft/carrying away/retaining property, the offender voluntarily causes or attempts to cause to any person: death, hurt, or wrongful restraint, or fear of instant death, hurt, or wrongful restraint. Elements: theft/extortion + force/threat of force.","17",["IPC S390 robbery definition theft extortion force threat instant death hurt wrongful restraint"]],
["392","Punishment for robbery","Rigorous imprisonment up to 10 years + fine. If on highway between sunset and sunrise: up to 14 years.","17",["IPC S392 robbery ten years fine highway sunset sunrise fourteen"]],
["395","Punishment for dacoity","Life imprisonment or rigorous imprisonment up to 10 years + fine.","17",["IPC S395 dacoity life ten years fine rigorous"]],
["396","Dacoity with murder","Every member of group committing dacoity where one member commits murder: death, or life imprisonment, or rigorous imprisonment up to 10 years + fine.","17",["IPC S396 dacoity murder death life ten years every member group"]],
["397","Robbery/dacoity with deadly weapon","If offender uses deadly weapon or causes grievous hurt at time of committing robbery/dacoity: minimum 7 years.","17",["IPC S397 deadly weapon minimum seven years robbery dacoity"]],
["403","Dishonest misappropriation of movable property","Imprisonment up to 2 years or fine or both. Distinguished from CBT: no entrustment needed; offender comes into possession innocently and then misappropriates.","17",["IPC S403 dishonest misappropriation movable property two years fine no entrustment CBT difference"]],
["405","Criminal breach of trust — definition","Being entrusted with property, dishonestly misappropriating or converting to own use or disposing of in violation of any direction of law or legal contract: CBT. Three elements: (1) entrustment; (2) property; (3) dishonest misappropriation/conversion/disposal.","17",["IPC S405 CBT definition entrustment property dishonest misappropriation conversion disposal three elements"]],
["406","Punishment for CBT","Imprisonment up to 3 years or fine or both.","17",["IPC S406 CBT three years fine punishment"]],
["409","CBT by public servant/banker","Life imprisonment or up to 10 years + fine.","17",["IPC S409 CBT public servant banker life ten years fine"]],
["411","Receiving stolen property","Whoever dishonestly receives or retains stolen property knowing it to be stolen: imprisonment up to 3 years or fine or both.","17",["IPC S411 receiving stolen property three years fine dishonestly knows"]],
["414","Assisting in concealment of stolen property","Voluntarily assisting in concealing or disposing of stolen property knowing it to be stolen: imprisonment up to 3 years or fine or both.","17",["IPC S414 assisting concealment stolen property three years fine"]],
["415","Cheating — definition","Deceiving any person and: (a) dishonestly or fraudulently inducing delivery of property; or (b) intentionally inducing to do or omit to do anything likely to cause damage or harm. The deception must have been the causa causans — the moving cause — of the delivery/act. Mere breach of promise ≠ cheating unless dishonest intent existed from the start.","17",["IPC S415 cheating definition deception dishonest fraudulent induce deliver property harm causa causans breach promise intent start"]],
["417","Punishment for cheating","Imprisonment up to 1 year or fine or both.","17",["IPC S417 cheating one year fine punishment"]],
["420","Cheating + inducing delivery of property","Whoever cheats and thereby dishonestly induces delivery of property or alteration/destruction of valuable security: imprisonment up to 7 years + fine. S.420 is IPC's most commonly invoked fraud provision.","17",["IPC S420 cheating inducing delivery property seven years fine valuable security most common fraud"]],
["425","Mischief — definition","With intent to cause wrongful loss/damage to public or any person, causing destruction of any property or such change as destroys/diminishes its value or utility. Property must belong to someone other than the accused.","17",["IPC S425 mischief wrongful loss damage destroy property value utility not accused"]],
["426","Punishment for mischief","Imprisonment up to 3 months or fine or both.","17",["IPC S426 mischief three months fine punishment"]],
["436","Mischief by fire to destroy dwelling","Life imprisonment or imprisonment up to 10 years + fine.","17",["IPC S436 mischief fire destroy dwelling life ten years fine"]],
["441","Criminal trespass","Entering property with intent to commit offence or to intimidate, insult or annoy; or remaining unlawfully with such intent: criminal trespass.","17",["IPC S441 criminal trespass enter property offence intimidate insult annoy remain unlawfully intent"]],
["447","Punishment for criminal trespass","Imprisonment up to 3 months or fine up to Rs 500 or both.","17",["IPC S447 criminal trespass three months five hundred fine"]],
["448","Punishment for house-trespass","Imprisonment up to 1 year or fine up to Rs 1,000 or both.","17",["IPC S448 house-trespass one year thousand rupees"]],
["450","House-trespass to commit offence punishable with life imprisonment","Imprisonment up to 10 years + fine.","17",["IPC S450 house-trespass life imprisonment offence ten years fine"]],
["454","Lurking house-trespass/house-breaking to commit imprisonment offence","Imprisonment up to 3 years + fine.","17",["IPC S454 lurking house-trespass house-breaking three years fine imprisonment offence"]],
["457","Lurking house-trespass/house-breaking by night to commit offence","Imprisonment up to 5 years + fine.","17",["IPC S457 house-breaking night five years fine offence imprisonment"]],
["458","Lurking house-trespass/house-breaking by night after preparation for hurt","Imprisonment up to 14 years + fine.","17",["IPC S458 lurking house-breaking night preparation hurt fourteen years fine"]],
["463","Forgery — definition","Making false document/electronic record with intent to cause damage/injury to public or any person; to support any claim or title; to cause fraud. The false document must be made with a specific intent.","18",["IPC S463 forgery false document electronic record intent damage fraud claim title"]],
["465","Punishment for forgery","Imprisonment up to 2 years or fine or both.","18",["IPC S465 forgery two years fine punishment"]],
["466","Forgery of court record/public register","Forgery of record of Court, public register, or certificate/document made by public officer in official capacity: imprisonment up to 7 years + fine.","18",["IPC S466 forgery court record public register seven years fine officer"]],
["467","Forgery of valuable security/will","Life imprisonment or imprisonment up to 10 years + fine.","18",["IPC S467 forgery valuable security will life ten years fine"]],
["468","Forgery for cheating","Forging document to use for cheating: imprisonment up to 7 years + fine.","18",["IPC S468 forgery cheating seven years fine"]],
["469","Forgery to harm reputation","Forging document intending to harm reputation: imprisonment up to 3 years + fine.","18",["IPC S469 forgery harm reputation three years fine"]],
["471","Using forged document as genuine","Using as genuine any document known to be forged: same punishment as for forging such document.","18",["IPC S471 using forged document genuine same punishment forgery"]],
["477A","Falsification of accounts","Clerk/officer/servant wilfully falsifying books, records, electronic records, accounts with intent to defraud: imprisonment up to 7 years or fine or both.","18",["IPC S477A falsification accounts clerk servant wilfully defraud seven years fine"]],
["493","Cohabitation by deceit inducing belief of marriage","Man inducing woman to believe she is lawfully married to him by deceit and cohabiting: imprisonment up to 10 years + fine.","20",["IPC S493 cohabitation deceit marriage ten years fine woman"]],
["494","Bigamy — marrying again during lifetime of spouse","Marriage void by reason of previous living spouse: imprisonment up to 7 years + fine.","20",["IPC S494 bigamy seven years fine living spouse"]],
["495","Bigamy with concealment","Bigamy with concealment of former marriage: imprisonment up to 10 years + fine.","20",["IPC S495 bigamy concealment ten years fine"]],
["498","Enticing away married woman","Taking/enticing away married woman from husband with intent that she may have illicit intercourse: imprisonment up to 2 years or fine or both.","20",["IPC S498 enticing married woman illicit intercourse two years fine"]],
["498A","Husband or relative of husband causing cruelty","Husband or relative subjecting woman to cruelty: imprisonment up to 3 years + fine. Cognizable, non-bailable. Cruelty: conduct likely to drive to suicide or cause grave injury/danger to life; harassment with view to coerce to meet unlawful demand for property/dowry.","20",["IPC S498A cruelty husband relative three years fine cognizable non-bailable suicide grave injury dowry unlawful demand"]],
["499","Defamation — definition and ten exceptions","Making/publishing any imputation concerning any person intending to harm/knowing it will harm reputation: defamation. Ten exceptions including: (1) truth for public good; (2) fair comment on public servant; (3) fair comment on public conduct; (4) publication of report of court proceedings; (5) merits of judicial decision; (6) literary/artistic criticism; (7) censure by authority over person; (8) accusation made in good faith to authority; (9) imputation for protection of interests; (10) caution in good faith.","21",["IPC S499 defamation ten exceptions truth public good public servant court judicial criticism accusation good faith caution"]],
["500","Punishment for defamation","Simple imprisonment up to 2 years or fine or both.","21",["IPC S500 defamation two years simple imprisonment fine"]],
["503","Criminal intimidation — definition","Threatening with injury to person/reputation/property to cause alarm or to compel/prevent any act: criminal intimidation. Fear of injury need not actually be caused — threat is enough.","22",["IPC S503 criminal intimidation threat injury alarm compel prevent act fear"]],
["506","Punishment for criminal intimidation","Plain: up to 2 years or fine or both. Aggravated (threat of death/grievous hurt/fire/capital offence): imprisonment up to 7 years or fine or both.","22",["IPC S506 criminal intimidation two years seven years death grievous hurt fire fine"]],
["509","Insult modesty of woman by word/gesture","Simple imprisonment up to 3 years + fine.","22",["IPC S509 insult modesty woman word gesture three years fine"]],
["511","Attempting to commit offences — punishment","Whoever attempts to commit offence punishable with imprisonment, and in such attempt does any act towards commission: half the maximum imprisonment (or fine or both) provided for that offence.","23",["IPC S511 attempt commit offence half maximum imprisonment fine punishment"]],
]);

// ══════════════════════════════════════════════
// CONTRACT ACT 1872 — all remaining sections
// ══════════════════════════════════════════════
addAll("Indian Contract Act, 1872","ICA","Civil Law / Contract",[
["1","Short title","This Act may be called the Indian Contract Act, 1872. It extends to the whole of India. All agreements are contracts if made by free consent of parties competent to contract, for lawful consideration and with lawful object, and are not hereby expressly declared to be void.","1",["ICA S1 short title India 1872 agreement contract conditions free consent competent lawful"]],
["3","Communication acceptance and revocation of proposals","The communication of proposals, the acceptance of proposals, and the revocation of proposals and acceptances respectively, are deemed to be made by any act or omission of the party proposing, accepting or revoking, by which he intends to communicate such proposal, acceptance or revocation, or which has the effect of communicating it.","1",["ICA S3 communication proposal acceptance revocation act omission intend communicate effect"]],
["4","Communication when complete","The communication of a proposal is complete when it comes to the knowledge of the person to whom it is made. The communication of an acceptance is complete as against the proposer, when it is put in a course of transmission to him. The communication of a revocation is complete as against the person who makes it, when it is put into a course of transmission.","1",["ICA S4 communication complete proposal acceptance revocation knowledge put transmission postal rule"]],
["5","Revocation of proposals and acceptances","A proposal may be revoked at any time before the communication of its acceptance is complete as against the proposer. An acceptance may be revoked at any time before the communication of the acceptance is complete as against the acceptor.","1",["ICA S5 revocation proposal acceptance time complete proposer acceptor"]],
["6","Revocation how made","A proposal is revoked: by communication of notice of revocation by the proposer to the other party; by the lapse of time prescribed or reasonable time if none prescribed; by failure of acceptor to fulfil condition precedent; by death or insanity of proposer (if offeree knows).","1",["ICA S6 revocation how made notice lapse time condition precedent death insanity proposer"]],
["7","Acceptance must be absolute","In order to convert a proposal into a promise, the acceptance must be absolute and unqualified, and must be expressed in some usual and reasonable manner. A conditional acceptance is no acceptance but a counter-offer.","1",["ICA S7 acceptance absolute unqualified usual reasonable conditional counter-offer"]],
["8","Acceptance by performing conditions","Performance of the conditions of a proposal, or the acceptance of any consideration for a reciprocal promise which may be offered with a proposal, is an acceptance of the proposal.","1",["ICA S8 acceptance performing conditions consideration reciprocal promise"]],
["9","Promises express and implied","In so far as the proposal or acceptance of any promise is made in words, the promise is said to be express. In so far as such proposal or acceptance is made otherwise than in words, the promise is said to be implied.","1",["ICA S9 promise express implied words otherwise"]],
["10","What agreements are contracts","All agreements are contracts if made by free consent of parties competent to contract, for a lawful consideration and with a lawful object, and are not hereby expressly declared to be void. The four essentials: free consent; competency; lawful consideration; lawful object.","1",["ICA S10 agreement contract free consent competent lawful consideration object four essentials"]],
["13","Consent","Two or more persons are said to consent when they agree upon the same thing in the same sense. Consensus ad idem — meeting of minds. If parties mean different things, there is no contract due to mistake.","2",["ICA S13 consent agree same thing same sense consensus ad idem meeting minds mistake"]],
["14","Free consent — five vitiating factors","Consent is free when not caused by: coercion (S.15); undue influence (S.16); fraud (S.17); misrepresentation (S.18); mistake (S.20-22). If consent is caused by any of these factors, the contract is voidable at the option of the party whose consent was so caused.","2",["ICA S14 free consent vitiating factors coercion undue influence fraud misrepresentation mistake five voidable"]],
["15","Coercion — definition","Committing, or threatening to commit, any act forbidden by the IPC; or the unlawful detaining, or threatening to detain, any property, to the prejudice of any person, with the intention of causing any person to enter into an agreement.","2",["ICA S15 coercion IPC forbidden act unlawful detaining property intention enter agreement"]],
["16","Undue influence","A contract is induced by undue influence where the relations between the parties are such that one party is in a position to dominate the will of the other and uses that position to obtain an unfair advantage over the other. Position to dominate: real or apparent authority over other; fiduciary relation; person with mental capacity affected.","2",["ICA S16 undue influence dominate will position fiduciary authority mental capacity unfair advantage"]],
["17","Fraud — definition","Fraud means: suggestion of a fact which is not true (known to be false); active concealment of a fact with knowledge or belief; promise made without intention to perform; any other act fitted to deceive; any such act specially declared fraudulent by law.","2",["ICA S17 fraud false suggestion active concealment promise without intention deceive"]],
["18","Misrepresentation","Misrepresentation means: positive assertion not warranted by information of person making it; breach of duty gaining advantage by misleading another; causing party to make mistake as to substance of agreement. Distinction from fraud: misrepresentation is innocent (no knowledge of falsity).","2",["ICA S18 misrepresentation positive assertion duty misleading mistake substance innocent no knowledge falsity"]],
["19","Voidability — contract caused by coercion/fraud/misrepresentation","When consent to an agreement is caused by coercion, fraud or misrepresentation, the agreement is a contract voidable at the option of the party whose consent was so caused. Party may rescind or insist on performance with restoration to true position.","2",["ICA S19 voidable contract coercion fraud misrepresentation option rescind insist performance"]],
["19A","Power to set aside contract induced by undue influence","When consent to an agreement is caused by undue influence, the agreement is a contract voidable at the option of the party whose consent was so caused. Court may set it aside either absolutely or on terms as it deems just.","2",["ICA S19A voidable undue influence court set aside absolutely just terms"]],
["20","Agreement void where both parties under mistake of fact","Where both the parties to an agreement are under a mistake as to a matter of fact essential to the agreement, the agreement is void. Bilateral mistake of essential fact: void. Unilateral mistake: generally no relief.","2",["ICA S20 bilateral mistake fact essential agreement void unilateral generally no relief"]],
["21","Effect of mistakes as to law","A contract is not voidable because it was caused by a mistake as to any law in force in India. A mistake of fact in a foreign country is treated as a mistake of fact.","2",["ICA S21 mistake law India not voidable foreign country treated fact"]],
["22","Contract caused by mistake of one party as to matter of fact","A contract is not voidable merely because it was caused by one of the parties to it being under a mistake as to a matter of fact.","2",["ICA S22 unilateral mistake not voidable one party only"]],
["23","Lawful and unlawful considerations and objects","Consideration or object is lawful unless: forbidden by law; would defeat provisions of any law; fraudulent; involves injury to person or property of another; immoral; opposed to public policy.","2",["ICA S23 lawful unlawful consideration object forbidden law defeat provisions fraud injury immoral public policy"]],
["24","Agreements void if considerations and objects unlawful in part","If any part of a single consideration for one or more objects, or any one or several considerations for a single object, is unlawful, the agreement is void.","2",["ICA S24 void unlawful part consideration object single several agreement"]],
["25","Agreement without consideration void — exceptions","An agreement without consideration is void unless: it is made in writing and registered; or is a promise to compensate for something already done voluntarily; or is a promise to pay a time-barred debt.","2",["ICA S25 void no consideration exceptions written registered compensate voluntary past consideration time-barred debt"]],
["26","Agreement in restraint of marriage void","Every agreement in restraint of the marriage of any person, other than a minor, is void.","2",["ICA S26 restraint marriage void except minor"]],
["27","Agreement in restraint of trade void","Every agreement by which any one is restrained from exercising a lawful profession, trade or business of any kind, is to that extent void. Exception: goodwill on sale of business — reasonable restraint valid.","2",["ICA S27 restraint trade void exception goodwill sale business reasonable"]],
["28","Agreement in restraint of legal proceedings void","Every agreement, by which any party thereto is restricted absolutely from enforcing his rights under or in respect of any contract, by the usual legal proceedings in the ordinary tribunals, or which limits the time within which he may enforce his rights, is void.","2",["ICA S28 restraint legal proceedings void absolute limit time enforce rights arbitration exception"]],
["29","Agreements void for uncertainty","Agreements the meaning of which is not certain, or capable of being made certain, are void.","2",["ICA S29 uncertainty void agreement meaning not certain capable"]],
["30","Agreements by way of wager void","Agreements by way of wager are void; and no suit shall lie for recovering anything alleged to be won on any wager, or entrusted to any person to abide the result of any uncertain event. Exceptions: horse racing in certain States; games of skill.","2",["ICA S30 wager void gambling bet uncertain event horse racing skill exception"]],
["32","Contingent contracts","Contingent contract is one to do or not do something on the happening or non-happening of some uncertain future event collateral to it. Not enforceable by law unless and until event happens.","3",["ICA S32 contingent contract do not do uncertain future event collateral enforceable event happens"]],
["33","Enforcement of contract contingent on event happening","Contingent contracts to do or not to do anything if an uncertain future event happens, cannot be enforced by law unless and until that event has happened.","3",["ICA S33 enforcement contingent event happening uncertain future cannot enforce until"]],
["36","Agreement contingent on impossible events void","Contingent agreements to do or not to do anything, if an impossible event happens, are void, whether the impossibility of the event is known or not to the parties to the agreement at the time when it is made.","3",["ICA S36 contingent impossible event void whether known or not"]],
["37","Obligation of parties to perform","The parties to a contract must either perform, or offer to perform, their respective promises, unless such performance is dispensed with or excused under the provisions of this Act, or of any other law.","4",["ICA S37 obligation perform parties promises dispensed excused provisions other law"]],
["38","Effect of refusal to accept offer of performance","Where a promisor has made an offer of performance to the promisee, and the offer has not been accepted, the promisor is not responsible for non-performance, nor does he thereby lose his rights under the contract.","4",["ICA S38 offer performance refused not responsible non-performance rights contract"]],
["40","Person by whom promise is to be performed","If it appears from the nature of the case that it was the intention of the parties to any contract that any promise contained in it should be performed by the promisor himself, such promise must be performed by the promisor.","4",["ICA S40 promise promisor himself personal nature contract parties intention"]],
["41","Effect of accepting performance from third person","When a promisee accepts performance of the promise from a third person, he cannot afterwards enforce it against the promisor.","4",["ICA S41 third person performance accepted promisee cannot enforce against promisor"]],
["45","Devolution of joint liabilities","When two or more persons have made a joint promise, the promisee may, in the absence of express agreement to the contrary, compel any one or more of them to perform the whole of the promise.","4",["ICA S45 joint promise compel any one whole performance promisor liability"]],
["46","Time for performance of promise where no application is to be made and no time is specified","Where by the contract, a promisor is to perform his promise without application by the promisee, and no time for performance is specified, the engagement must be performed within a reasonable time.","4",["ICA S46 no time specified perform reasonable time without application promisor"]],
["47","Time and place for performance of promise where time is specified and no application to be made","When a promise is to be performed on a certain day, and the promisor, without application by the promisee, is to perform it, the promisor may perform it at any time during the usual hours of business on such day and at the place at which the promise ought to be performed.","4",["ICA S47 time specified certain day usual hours business promisor perform"]],
["48","Application for performance on certain day to be at proper time and place","When a promise is to be performed on a certain day, and the promisor is to perform it on application by the promisee, it is the duty of the promisee to apply for performance at a proper place and within the usual hours of business.","4",["ICA S48 application performance certain day promisee duty proper place usual hours"]],
["49","Place for performance of promise where no application to be made and no place fixed for performance","When a promise is to be performed without application by the promisee, and no place is fixed for the performance of it, it is the duty of the promisor to apply to the promisee to appoint a reasonable place for the performance of the promise, and to perform it at such place.","4",["ICA S49 no place fixed performance promisor duty apply promisee appoint reasonable place"]],
["50","Performance in manner or at time prescribed or sanctioned by promisee","The performance of any promise may be made in any manner, or at any time which the promisee prescribes or sanctions.","4",["ICA S50 performance manner time promisee prescribes sanctions any manner any time"]],
["51","Promisor not bound to perform unless reciprocal promisee ready","When a contract consists of reciprocal promises to be simultaneously performed, no promisor need perform his promise unless the promisee is ready and willing to perform his reciprocal promise.","4",["ICA S51 reciprocal promise simultaneous performance promisor not bound unless promisee ready willing"]],
["52","Order of performance of reciprocal promises","Where the order in which reciprocal promises are to be performed is expressly fixed by the contract, they shall be performed in that order; and where the order is not expressly fixed by the contract, they shall be performed in that order which the nature of the transaction requires.","4",["ICA S52 order performance reciprocal promises express fixed nature transaction"]],
["53","Liability of party preventing event on which contract is to take effect","When a contract contains reciprocal promises, and one party to the contract prevents the other from performing his promise, the contract becomes voidable at the option of the party so prevented.","4",["ICA S53 preventing performance reciprocal promise voidable option prevented party"]],
["54","Effect of default as to that promise which should be first performed","When a contract consists of reciprocal promises, such that one of them cannot be performed, or that its performance cannot be claimed, till the other has been performed, and the promisor of the promise last mentioned fails to perform it, such promisor cannot claim the performance of the reciprocal promise.","4",["ICA S54 default first performed reciprocal promise promisor fails cannot claim"]],
["55","Effect of failure to perform at fixed time in contract in which time is essential","When a party to a contract promises to do a certain thing at or before a specified time, and fails to do any such thing at or before the specified time, the contract, or so much of it as has not been performed, becomes voidable at the option of the promisee, if the intention of the parties was that time should be of the essence.","4",["ICA S55 time essence fixed specified time failure voidable option promisee"]],
["56","Agreement to do impossible act — frustration","An agreement to do an act impossible in itself is void. A contract to do an act which, after the contract is made, becomes impossible, or, by reason of some event which the promisor could not prevent, unlawful, becomes void when the act becomes impossible or unlawful. Doctrine of frustration: supervening impossibility or illegality discharges the contract.","4",["ICA S56 frustration impossible act void supervening impossibility illegality discharges contract doctrine Taylor Caldwell"]],
["57","Reciprocal promise to do things legal and illegal","Where persons reciprocally promise, firstly, to do certain things which are legal, and secondly, under specified circumstances, to do certain other things which are illegal, the first set of promises is a contract, but the second is a void agreement.","4",["ICA S57 reciprocal promise legal illegal first valid second void agreement"]],
["58","Alternative promise, one branch being illegal","In the case of an alternative promise, one branch of which is legal and the other illegal, the legal branch alone can be enforced.","4",["ICA S58 alternative promise legal illegal branch legal only enforced"]],
["63","Effect of novation rescission and alteration","If the parties to a contract agree to substitute a new contract for it, or to rescind or alter it, the original contract need not be performed: Novation (new contract replaces old); Rescission (parties agree to abandon contract); Alteration (parties agree to modify terms).","5",["ICA S63 novation rescission alteration new contract original need not perform agree substitute abandon modify"]],
["64","Consequences of rescission of voidable contract","When a person at whose option a contract is voidable rescinds it, the other party thereto need not perform any promise therein contained in which he is the promisor. The party rescinding a voidable contract shall, if he has received any benefit thereunder from another party to such contract, restore such benefit, so far as may be, to the person from whom it was received.","5",["ICA S64 rescission voidable contract other party not perform restore benefit received option"]],
["65","Obligation of person who has received advantage under void agreement","When an agreement is discovered to be void, or when a contract becomes void, any person who has received any advantage under such agreement or contract is bound to restore it, or to make compensation for it, to the person from whom he received it.","5",["ICA S65 void agreement advantage received restore compensation person bound"]],
["66","Mode of communicating or revoking rescission of voidable contract","The rescission of a voidable contract may be communicated or revoked in the same manner and subject to the same rules, as apply to the communication or revocation of a proposal.","5",["ICA S66 communicating revoking rescission voidable contract same rules proposal revocation"]],
["67","Effect of neglect of promisee to afford promisor reasonable facilities for performance","If any promisee neglects or refuses to afford the promisor reasonable facilities for the performance of his promise, the promisor is excused by such neglect or refusal as to any non-performance caused thereby.","5",["ICA S67 neglect refuse reasonable facilities performance promisor excused non-performance"]],
["73","Compensation for loss or damage caused by breach","When a contract has been broken, the party who suffers by such breach is entitled to receive compensation for any loss naturally arising in the usual course of things from such breach or which the parties knew when they made the contract to be likely to result from the breach. Remote or indirect loss not compensable. Rule in Hadley v Baxendale.","6",["ICA S73 compensation loss damage breach natural usual course Hadley Baxendale not remote indirect knew parties"]],
["74","Compensation for breach where penalty stipulated","When a contract has been broken, if a sum is named in the contract as the amount to be paid in case of breach, or if the contract contains any other stipulation by way of penalty, the party complaining of the breach is entitled to receive from the party who has broken it reasonable compensation not exceeding the amount so named or the penalty stipulated for.","6",["ICA S74 penalty stipulated breach reasonable compensation not exceeding named amount ceiling ONGC Saw Pipes"]],
["75","Party rightfully rescinding contract entitled to compensation","A person who rightfully rescinds a contract is entitled to compensation for any damage which he has sustained through the non-fulfilment of the contract.","6",["ICA S75 rightful rescission compensation non-fulfilment damage sustained"]],
["124","Contract of indemnity defined","A contract by which one party promises to save the other from loss caused to him by the conduct of the promisor himself, or by the conduct of any other person, is called a contract of indemnity.","8",["ICA S124 indemnity contract promise save loss promisor third person conduct definition"]],
["125","Rights of indemnity-holder when sued","The promisee in a contract of indemnity, acting within the scope of his authority, is entitled to recover from the promisor all damages which he may be compelled to pay in any suit in respect of any matter to which the promise to indemnify applies.","8",["ICA S125 indemnity holder rights sued recover damages compelled pay scope authority"]],
["126","Contract of guarantee defined","A contract of guarantee is a contract to perform the promise, or discharge the liability, of a third person in case of his default. The person who gives the guarantee is called the surety; the person in respect of whose default the guarantee is given is called the principal debtor; and the person to whom the guarantee is given is called the creditor.","8",["ICA S126 guarantee contract surety principal debtor creditor third person default promise liability"]],
["127","Consideration for guarantee","Anything done, or any promise made, for the benefit of the principal debtor, may be a sufficient consideration to the surety for giving the guarantee.","8",["ICA S127 consideration guarantee benefit principal debtor sufficient"]],
["128","Surety's liability","The liability of the surety is co-extensive with that of the principal debtor, unless it is otherwise provided by the contract. Surety is liable for entire debt of principal debtor — not just guarantee amount.","8",["ICA S128 surety liability co-extensive principal debtor entire debt unless otherwise contract"]],
["133","Discharge of surety by variance in terms of contract","Any variance, made without the surety's consent, in the terms of the contract between the principal debtor and the creditor, discharges the surety as to transactions subsequent to the variance.","8",["ICA S133 discharge surety variance terms contract without consent principal debtor creditor subsequent"]],
["134","Discharge of surety by release or discharge of principal debtor","The surety is discharged by any contract between the creditor and the principal debtor, by which the principal debtor is released, or by any act or omission of the creditor, the legal consequence of which is the discharge of the principal debtor.","8",["ICA S134 discharge surety release principal debtor creditor contract act omission"]],
["135","Discharge of surety when creditor compounds with or releases principal debtor","A contract between the creditor and the principal debtor, by which the creditor makes a composition with, or promises to give time to, or not to sue, the principal debtor, discharges the surety, unless the surety assents to such contract.","8",["ICA S135 discharge surety composition time creditor principal debtor unless assent"]],
["139","Guarantee obtained by misrepresentation invalid","Any guarantee which the creditor has obtained by means of misrepresentation made by the creditor, or with the creditor's knowledge and assent, concerning a material part of the transaction, is invalid.","8",["ICA S139 guarantee misrepresentation creditor invalid material part transaction"]],
["140","Rights of surety on payment or performance","Where a guaranteed debt has become due, or default of the principal debtor to perform a guaranteed duty has taken place, the surety, upon payment or performance of all that he is liable for, is invested with all the rights which the creditor had against the principal debtor.","8",["ICA S140 surety rights subrogation payment performance creditor rights principal debtor"]],
["141","Surety's right to benefit of creditor's securities","A surety is entitled to the benefit of every security which the creditor has against the principal debtor at the time when the contract of suretyship is entered into.","8",["ICA S141 surety right security creditor principal debtor suretyship time entered"]],
["145","Implied promise to indemnify surety","In every contract of guarantee there is an implied promise by the principal debtor to indemnify the surety; and the surety is entitled to recover from the principal debtor whatever sum he may have rightfully paid under the guarantee.","8",["ICA S145 implied promise indemnify surety principal debtor recover paid guarantee rightfully"]],
["148","Bailment defined","Delivery of goods by one person to another for some purpose, upon a contract that they shall, when the purpose is accomplished, be returned or otherwise disposed of according to the directions of the person delivering them. The person delivering: bailor. Person to whom delivered: bailee.","9",["ICA S148 bailment delivery goods purpose return dispose bailor bailee contract"]],
["149","Delivery to bailee how made","Delivery to the bailee may be made by doing anything which has the effect of putting the goods in the possession of the intended bailee or of any person authorised to hold them on his behalf.","9",["ICA S149 delivery bailee possession authorised effect goods intended"]],
["150","Bailor's duty to disclose faults in goods bailed","The bailor is bound to disclose to the bailee faults in the goods bailed, of which the bailor is aware, and which materially interfere with the use of them, or expose the bailee to extraordinary risk; and if he does not make such disclosure, he is responsible for damage arising to the bailee directly from such faults.","9",["ICA S150 bailor duty disclose faults goods bailee aware interfere risk responsible damage"]],
["151","Care to be taken by bailee","In all cases of bailment, the bailee is bound to take as much care of the goods bailed to him as a man of ordinary prudence would, under similar circumstances, take of his own goods of the same bulk, quality and value as the goods bailed.","9",["ICA S151 bailee care ordinary prudence own goods similar circumstances bulk quality value"]],
["154","Liability of bailee making unauthorized use of goods bailed","If the bailee makes any use of the goods bailed, which is not according to the conditions of the bailment, he is liable to make compensation to the bailor for any damage arising to the goods from or during such use.","9",["ICA S154 bailee unauthorized use goods compensation bailor damage"]],
["160","Bailee's duty to return goods","It is the duty of the bailee to return, or deliver according to the bailor's directions, the goods bailed, without demand, as soon as the time for which they were bailed has expired, or the purpose for which they were bailed has been accomplished.","9",["ICA S160 bailee duty return deliver goods bailor directions time purpose accomplished"]],
["161","Bailee's responsibility when goods not returned","If, by the default of the bailee, the goods are not returned, delivered or tendered at the proper time, he is responsible to the bailor for any loss, destruction or deterioration of the goods from that time.","9",["ICA S161 bailee default not returned responsible loss destruction deterioration from that time"]],
["164","Bailee not responsible on re-delivery to bailor without title","If the bailor has no title to the goods, and the bailee, in good faith, delivers them back to, or according to the directions of, the bailor, the bailee is not responsible to the owner in respect of such delivery.","9",["ICA S164 bailee not responsible no title bailor good faith delivers returns directions owner"]],
["168","Right of finder of goods — may sue for specific reward","The finder of goods has no right to sue the owner for compensation for trouble and expense voluntarily incurred by him in preserving the goods and finding out the owner; but he may retain the goods against the owner until he receives such compensation; and, where the owner has offered a specific reward for the return of goods lost, the finder may sue for such reward, and may retain the goods until he receives it.","9",["ICA S168 finder goods sue specific reward retain compensation preserve owner"]],
["169","When finder of goods may sell them","When a thing which is commonly the subject of sale is lost, if the owner cannot with reasonable diligence be found, or if he refuses upon demand to pay the lawful charges of the finder, the finder may sell it if the owner cannot be found; and if the goods are in danger of perishing and the owner cannot be found.","9",["ICA S169 finder goods sell owner not found refuse pay charges danger perishing"]],
["182","Agent and principal defined","An agent is a person employed to do any act for another, or to represent another in dealings with third persons. The person for whom such act is done, or who is so represented, is called the principal. Agent represents principal in dealings with third parties.","10",["ICA S182 agent principal definition employed act represent dealings third persons"]],
["186","Agent's authority — express and implied","The authority of an agent may be expressed or implied. An authority is said to be expressed when it is given by words spoken or written. An authority is said to be implied when it is to be inferred from the circumstances of the case.","10",["ICA S186 agent authority express implied words spoken written inferred circumstances"]],
["188","Extent of agent's authority","An agent having an authority to do an act has authority to do every lawful thing which is necessary in order to do such act.","10",["ICA S188 extent agent authority act necessary lawful thing"]],
["190","Agent cannot delegate","An agent cannot lawfully employ another to perform acts which he has expressly or impliedly undertaken to perform personally, unless by the ordinary custom of trade a sub-agent may, or, from the nature of the agency, a sub-agent must, be employed.","10",["ICA S190 agent cannot delegate sub-agent custom trade personally unless nature agency"]],
["194","Relation of principal to persons appointed by agent to act in the business of agency","Where an agent, holding an express or implied authority to name another person to act for the principal in the business of the agency, has named another person accordingly, such person is not a sub-agent, but an agent of the principal for such part of the business of the agency as is entrusted to him.","10",["IPC ICA S194 agent appoints another principal directly agent not sub-agent business entrusted"]],
["197","Ratification may be express or implied","Ratification may be expressed or may be implied in the conduct of the person on whose behalf the acts are done. The principal ratifying an unauthorised act is bound by it as if it had been originally authorised.","10",["ICA S197 ratification express implied conduct unauthorised act bound originally authorised"]],
["202","Termination of agency where agent has interest in subject-matter","Where the agent has himself an interest in the property which forms the subject-matter of the agency, the agency cannot, in the absence of an express contract, be terminated to the prejudice of such interest.","10",["ICA S202 termination agency agent interest property subject-matter cannot terminate prejudice"]],
["206","Reasonable notice required for revocation of agency in certain cases","Reasonable notice must be given of the revocation or renunciation of an agency; otherwise the damage thereby resulting to the principal or the agent, as the case may be, must be made good to the one who suffers from the want of such notice.","10",["ICA S206 revocation agency reasonable notice damage principal agent suffers"]],
["211","Agent's duty in conducting principal's business","An agent is bound to conduct the business of his principal according to the directions given by the principal, or, in the absence of any such directions, according to the custom which prevails in doing business of the same kind at the place where the agent conducts such business.","10",["ICA S211 agent duty conduct principal business directions custom place absence"]],
["212","Skill and diligence required from agent","An agent is bound to conduct the business of the agency with as much skill as is generally possessed by persons engaged in similar business, unless the principal has notice of his want of skill. The agent is always bound to act with reasonable diligence, and to use such skill as he possesses.","10",["ICA S212 agent skill diligence general skill similar business principal notice reasonable"]],
["213","Agent's duty to render accounts","An agent is bound to render proper accounts to his principal on demand.","10",["ICA S213 agent duty render accounts principal demand"]],
["214","Agent's duty to communicate with principal in case of difficulty","It is the duty of an agent, in cases of difficulty, to use all reasonable diligence in communicating with his principal, and in seeking to obtain his instructions.","10",["ICA S214 agent duty communicate principal difficulty diligence instructions"]],
["215","Right of principal when agent deals on his own account in business of agency","If an agent deals on his own account in the business of the agency, without first obtaining the consent of his principal and acquainting him with all material circumstances which have come to his own knowledge on the subject, the principal may repudiate the transaction.","10",["ICA S215 agent own account business agency without consent principal repudiate material circumstances"]],
["218","Agent's right of retainer out of sums received on principal's account","An agent may retain, out of any sums received on account of the principal in the business of the agency, all moneys due to himself in respect of advances made or expenses properly incurred by him in conducting such business, and also such remuneration as may be payable to him for conducting such business.","10",["ICA S218 agent right retainer sums received principal advances expenses remuneration"]],
["219","Agent's right to remuneration","An agent is entitled to such remuneration as is agreed upon between him and the principal. In the absence of agreement: quantum meruit.","10",["ICA S219 agent remuneration agreed quantum meruit absence agreement"]],
["220","Agent not entitled to remuneration for business misconducted","An agent who is guilty of misconduct in the business of the agency is not entitled to any remuneration in respect of that part of the business which he has misconducted.","10",["ICA S220 agent no remuneration misconduct business part misconducted"]],
["221","Agent's lien on principal's property","In the absence of any contract to the contrary, an agent is entitled to retain goods, papers, and other property, whether movable or immovable, of the principal received by him, until the amount due to himself for commission, disbursements, and services in respect of the same has been paid or accounted for to him.","10",["ICA S221 agent lien retain property movable immovable commission disbursements services paid"]],
["226","Enforcement of agency contract","In the absence of an agreement to the contrary, all parties to a contract can sue one another: the promisee can sue the promisor; the third party beneficiary of a contract through the agent can sue the principal.","10",["ICA S226 enforce agency contract parties sue promisor promisee third party principal"]],
["229","Liability of principal to third parties for agent's fraudulent acts","The principal is liable for the fraud or misrepresentation of agents acting in the course of their authority.","10",["ICA S229 principal liable agent fraud misrepresentation course authority third parties"]],
["230","Agent cannot personally enforce or be bound","In the absence of any contract to that effect, an agent cannot personally enforce contracts entered into by him on behalf of his principal, nor is he personally bound by them.","10",["ICA S230 agent not personally enforce bound contracts principal behalf absence contract"]],
["231","Rights of parties to a contract made by agent not disclosed","If an agent makes a contract with a person who neither knows, nor has reason to suspect, that he is an agent, his principal may require the performance of the contract; but the other contracting party has, as against the principal, the same rights as he would have had as against the agent if the agent had been the principal.","10",["ICA S231 undisclosed principal agent rights performance third party rights same as against agent"]],
["232","Performance of contract with agent who contracts as principal","Where one of the contracting parties intends to deal with the agent as with a principal, and the agent is in fact a principal, then the contract may be enforced both by and against such agent.","10",["ICA S232 agent contracts as principal enforce both ways contract"]],
["233","Right of person dealing with agent personally liable","In cases where the agent is personally liable, a person dealing with him may hold either him or his principal, or both of them, liable.","10",["ICA S233 agent personally liable principal both hold either liable"]],
["234","Consequence of notice that agent has exceeded authority","If a person with whom an agent deals knew that the agent was acting beyond his authority, he cannot enforce the contract against the principal.","10",["ICA S234 notice agent exceeded authority cannot enforce principal"]],
["238","Effect of ratification of unauthorized acts","Where acts of an agent are ratified by the principal, such ratification relates back and is deemed to have effect from the time when the acts were done.","10",["ICA S238 ratification unauthorized acts relates back time done principal"]],
]);

// CrPC sections 211-484
addAll("Code of Criminal Procedure, 1973","CrPC","Criminal Procedure",[
["211","Contents of charge","Every charge shall state the offence and section, date and place of offence, person against whom committed, and property involved. Charge must be specific enough for accused to prepare defence. Any defect in charge does not vitiate trial unless accused was actually misled (prejudice test).","17",["CrPC S211 charge contents offence section date place property prejudice defence"]],
["216","Court may alter charge at any time before judgment","Court may alter or add to any charge at any time before judgment. If alteration likely to prejudice accused: adjournment given. If not: trial proceeds. Recall of witnesses permitted after alteration (S.217).","17",["CrPC S216 alter add charge judgment prejudice adjournment recall witnesses"]],
["218","Separate charges for distinct offences","For every distinct offence there shall be a separate charge, and every charge shall be tried separately. Exceptions: S.219 (same kind within 12 months), S.220 (same transaction), S.221 (doubt as to offence).","17",["CrPC S218 separate charges distinct offences each tried separately S219 S220 S221 exceptions"]],
["220","Trial for more than one offence in same transaction","Where same transaction gives rise to multiple offences, accused may be charged with and tried for all at one trial. 'Same transaction' is construed broadly — includes series of acts connected by time, place, purpose or continuity of action.","17",["CrPC S220 same transaction multiple offences one trial connected time place purpose"]],
["225","Public Prosecutor to conduct trial before Sessions Court","In every trial before a Court of Session, the prosecution shall be conducted by a Public Prosecutor. This is mandatory — trial vitiated if PP not present.","18",["CrPC S225 Public Prosecutor Sessions Court mandatory trial prosecution conduct"]],
["226","Opening prosecution case","On commitment, the prosecutor opens his case by describing the charge and stating what evidence he will produce to prove guilt. Opening statement stage.","18",["CrPC S226 opening prosecution case commitment charge evidence guilt describe"]],
["227","Discharge","If judge finds no sufficient ground for proceeding against accused, he shall discharge accused. Standard: not prima facie case. Stage: after prosecution materials considered, before framing charge. Discharge ≠ acquittal (not on merits).","18",["CrPC S227 discharge no sufficient ground prima facie before charge not acquittal"]],
["228","Framing of charge","If judge finds ground for presuming accused committed offence, charge framed in writing, read and explained to accused, who asked to plead guilty or claim trial.","18",["CrPC S228 framing charge writing read explained plead guilty claim trial presuming"]],
["229","Conviction on plea of guilty — Sessions","If accused pleads guilty, judge records plea and may in discretion convict.","18",["CrPC S229 conviction plea guilty Sessions Court judge discretion record"]],
["232","Acquittal after prosecution evidence — Sessions","If no evidence that accused committed offence after prosecution case: judge records acquittal. S.232 acquittal is on merits, unlike S.227 discharge.","18",["CrPC S232 acquittal no evidence prosecution case Sessions judge record merits"]],
["235","Judgment of acquittal or conviction — Sessions","After hearing arguments, judge gives judgment. In case of conviction: judge hears accused on sentence (S.235(2) mandatory). Judgment must give reasons.","18",["CrPC S235 judgment acquittal conviction Sessions sentence hearing accused mandatory S235(2) reasons"]],
["239","Discharge in warrant case by Magistrate","If Magistrate considers charge groundless on considering police report and documents, he shall discharge accused.","19",["CrPC S239 discharge Magistrate groundless charge police report documents warrant case"]],
["240","Framing of charge in warrant case","If Magistrate finds ground for presuming accused committed triable offence, charge framed in writing, read and explained.","19",["CrPC S240 framing charge warrant case Magistrate writing read explained"]],
["248","Acquittal or conviction in warrant case","Magistrate records acquittal if finds accused not guilty; records conviction if proves charge.","19",["CrPC S248 acquittal conviction warrant case Magistrate not guilty"]],
["251","Statement of accusation in summons case","Particulars of offence stated to accused and asked whether pleads guilty.","20",["CrPC S251 summons case particulars offence accused plead guilty"]],
["255","Acquittal or conviction in summons case","Magistrate acquits or convicts after hearing both sides in summons case.","20",["CrPC S255 acquittal conviction summons case Magistrate hearing both sides"]],
["260","Summary trial by first class Magistrate","CJM/Metropolitan Magistrate/first class Magistrate may try summarily: offences punishable with up to 2 years; theft/receiving stolen property value below Rs 2,000; dishonest misappropriation below Rs 2,000; assault/criminal force without serious injury; offences IPC Chapters VII-XI.","21",["CrPC S260 summary trial first class Magistrate two years Rs 2000 theft misappropriation assault"]],
["300","Persons once convicted or acquitted not to be tried for same offence","A person tried by competent court and convicted or acquitted cannot be tried again for the same offence (double jeopardy). Also bars trial on same facts for different offence that might have been charged at same trial.","23",["CrPC S300 double jeopardy same offence same facts convicted acquitted bar trial Article 20(2)"]],
["303","Right to be defended by pleader","Every accused person before Criminal Court may of right be defended by a pleader of his choice. Constitutional right (Article 22) + statutory right.","24",["CrPC S303 right defence pleader choice accused Article 22 constitutional statutory"]],
["304","Legal aid at State expense","Where accused in Sessions trial is not represented by pleader and cannot afford one, court shall assign pleader at State expense. Hussainara Khatoon: fundamental right.","24",["CrPC S304 legal aid State expense Sessions trial pleader assign indigent Hussainara fundamental"]],
["306","Tender of pardon — approver","CJM or Metropolitan Magistrate may tender pardon to any person concerned with offence in order to obtain his evidence. Approver's evidence must be corroborated.","24",["CrPC S306 pardon approver CJM Metropolitan evidence corroboration tender"]],
["309","Adjournment — day to day trial","Proceedings to continue day to day until witnesses examined. Courts must endeavour to complete rape/POCSO trials within 2 months (2018 amendment). Courts cannot grant more than 3 adjournments (2002 amendment).","24",["CrPC S309 adjournment day to day 2018 rape POCSO two months three adjournments 2002"]],
["313","Examination of accused","Court must examine accused to explain circumstances in evidence against him. Examination on oath NOT required. Statement not evidence but may be considered. False/evasive answers: adverse inference possible.","24",["CrPC S313 examine accused explain circumstances not on oath adverse inference not evidence"]],
["315","Accused as competent witness","Accused is competent but not compellable witness for defence. Can give evidence on oath in his own defence. Cannot be cross-examined on irrelevant facts. Article 20(3): protection against self-incrimination.","24",["CrPC S315 accused competent witness defence oath not compellable Article 20(3) self-incrimination"]],
["319","Power to proceed against other persons appearing guilty","Where during trial evidence shows person not accused committed offence, court may summon that person and proceed against him.","24",["CrPC S319 proceed other person appearing guilty evidence court summon"]],
["320","Compounding of offences","Certain IPC offences may be compounded by aggrieved party. Two categories: compoundable without court permission (S.320(1)); compoundable with court permission (S.320(2)). Court can quash FIR in non-compoundable offences if genuinely settled (Gian Singh 2012).","24",["CrPC S320 compounding offences IPC permission court aggrieved party Gian Singh non-compoundable quash"]],
["321","Withdrawal from prosecution","PP may with court consent withdraw from prosecution any time before judgment. If before charge framed: accused discharged. If after charge framed: acquittal results.","24",["CrPC S321 withdrawal prosecution PP court consent before charge discharged after charge acquitted"]],
["327","Court to be open — in camera exceptions","Criminal courts are open courts. Exception: trials for rape and sexual offences shall be conducted in camera if either party desires (S.327(2)). POCSO: child witness evidence always in camera.","24",["CrPC S327 open court public in camera rape sexual offences POCSO child witness"]],
["353","Judgment — pronouncement","Judgment must be pronounced in open court immediately after conclusion of trial or on a future date with notice. Must contain: points for determination, decision, reasons, offence specified, sentence.","25",["CrPC S353 judgment pronounce open court after trial notice reasons offence sentence points"]],
["357","Compensation to victims","Court may direct accused to pay compensation to victim. S.357(3): court may award compensation in addition to any fine. S.357A: State scheme for victim compensation. Mandatory consideration in all cases.","25",["CrPC S357 compensation victim accused pay fine addition S357A State scheme mandatory consideration"]],
["360","Release on probation or admonition","Person not under 21, convicted of fine-only offence or imprisonment up to 7 years, first offence: court may release on probation instead of sentencing. Admonition available for trivial first offences.","26",["CrPC S360 probation admonition under 21 seven years first offence rehabilitation release"]],
["362","Court cannot alter judgment after signing","Judgment signed is final — cannot be altered. Only clerical/arithmetical errors correctable. No review under criminal procedure (unlike civil). Grounds for appeal/revision but not review.","26",["CrPC S362 judgment signed final alter review prohibited clerical arithmetical error only"]],
["367","Death sentence — submitted to High Court for confirmation","Sessions Court death sentence must be submitted to High Court for confirmation. Not executable unless confirmed by High Court. High Court examines independently.","26",["CrPC S367 death sentence High Court confirmation Sessions Court not executed"]],
["374","Appeals — hierarchy","Conviction by High Court (extraordinary original) → Supreme Court. Conviction by Sessions/CJM/>7 years → High Court. Conviction by Magistrate → Sessions Court. No appeal from conviction by plea of guilty (unless plea was not voluntary).","29",["CrPC S374 appeal hierarchy Supreme Court High Court Sessions Magistrate seven years plea guilty no appeal"]],
["378","Appeal against acquittal by State","State Government may direct PP to file appeal against acquittal to Sessions (from Magistrate) or to High Court (from Sessions). 90 days to Sessions; 6 months to High Court.","29",["CrPC S378 appeal acquittal State PP Sessions High Court 90 days 6 months"]],
["389","Suspension of sentence pending appeal","Appellate Court may suspend execution of sentence and release accused on bail pending appeal — reasons in writing required.","29",["CrPC S389 suspend sentence bail pending appeal appellate court reasons writing"]],
["397","Revision","High Court/Sessions Court may call for record of any inferior court proceedings to examine correctness, legality, propriety of finding/sentence/order. Cannot interfere with interlocutory orders (S.397(2)).","30",["CrPC S397 revision High Court Sessions inferior court record correctness legality propriety no interlocutory"]],
["432","Remission of sentence","Appropriate Government (Central/State) may suspend or remit the whole or part of the punishment.","32",["CrPC S432 remission suspension sentence appropriate Government Central State"]],
["433A","Minimum 14 years for life imprisonment offenders","Person convicted of offence for which death is prescribed, if given life imprisonment: shall not be released unless served at least 14 years.","32",["CrPC S433A minimum fourteen years life imprisonment death prescribed offence mandatory"]],
["436","Bail in bailable offences — absolute right","Person accused of bailable offence and offering sureties must be released on bail. Right is absolute — police/court cannot refuse. No condition of surety means personal bond.","33",["CrPC S436 bailable offence bail absolute right surety personal bond police court cannot refuse"]],
["436A","Default bail after half maximum sentence","If accused has served half the maximum sentence for the offence (not punishable with death) as undertrial: entitled to release on personal bond as matter of right.","33",["CrPC S436A default bail half maximum sentence undertrial personal bond right mandatory"]],
["437","Bail in non-bailable offences","Release on bail discretionary. Cannot be granted if reasonable grounds to believe guilty of death or life imprisonment offence. Must consider: nature of accusation, character, risk of fleeing, prior record, likelihood of repeating.","33",["CrPC S437 bail non-bailable discretionary death life imprisonment reasonable grounds consider character risk"]],
["438","Anticipatory bail","Application to Sessions Court or High Court before arrest. Conditions imposed: cooperation, no tampering, no leaving country. SC: Sushila Aggarwal 2020 — anticipatory bail can continue till trial. Liberal construction.","33",["CrPC S438 anticipatory bail Sessions High Court conditions Sushila Aggarwal 2020 till trial liberal"]],
["439","High Court/Sessions Court — special bail powers","Can cancel bail granted by lower court if: bail on wrong principles; accused misusing bail; threatening witnesses; flight risk. Concurrent jurisdiction of High Court and Sessions Court.","33",["CrPC S439 bail cancel High Court Sessions wrong principles misuse threatening witnesses flight concurrent"]],
["482","Inherent powers of High Court","Inherent powers to: give effect to orders; prevent abuse of process; secure ends of justice. Can quash FIR, charge sheet, proceedings. Even non-compoundable cases can be quashed if genuinely settled (Gian Singh 2012).","37",["CrPC S482 inherent powers High Court quash FIR charge sheet proceedings abuse process ends justice Gian Singh 2012"]]
]);

